-- Exercise 10 -c
-- Nos muestra las liquidaciones sin deducciones, agregando una columna calculada que compruebe el valor bruto
-- Tabla A : pay.settlements T1
SELECT 
    T1.*,
    (net_weight_kg * price_per_kg_applied) AS check_gross_cop
FROM pay.settlements T1
WHERE 
    T1.settled_at >= '2026-09-30'
    AND T1.settled_at < '2026-10-01' 
    AND  deductions_amount=0;

